=== FILE: tick_timer_cov_tb.sv ===
// Coverage testbench for tick_timer.v (W = 16). Extends tick_timer_idle_tb.sv:
// it starts, counts, expires, clears and reloads the timer in one-shot and
// periodic modes, checks every result cycle-exactly, and toggles every
// reachable bit of the design. Structurally constant points at W = 16:
// rdata[31:16] (always zero) and unused_wdata (always zero).
`timescale 1ns / 1ps
module tick_timer_cov_tb;
    localparam logic [1:0] A_CTRL = 2'd0, A_LOAD = 2'd1, A_COUNT = 2'd2, A_STATUS = 2'd3;

    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    tick_timer #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .irq(irq));
    always #5 clk = ~clk;

    // Wait n rising edges, then 1 ns so the registers have settled.
    task automatic tick(input int n);
        repeat (n) @(posedge clk);
        #1;
    endtask

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected, input string what);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("MISMATCH %s: addr %0d read %h expected %h at %0t", what, a, rdata, expected, $time);
        end
    endtask

    task automatic expect_irq(input logic expected, input string what);
        checks++;
        if (irq !== expected) begin
            errors++;
            $display("MISMATCH %s: irq %b expected %b at %0t", what, irq, expected, $time);
        end
    endtask

    // One write, applied at the next rising edge; returns 1 ns after it.
    task automatic write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1; addr = a; wdata = d;
        @(posedge clk); #1;
        we = 1'b0; wdata = 32'd0;
    endtask

    initial begin
        // A: synchronous reset
        repeat (3) @(posedge clk);
        #1;
        rst_n = 1'b1;
        expect_reg(A_CTRL,   32'd0, "reset CTRL");
        expect_reg(A_LOAD,   32'd0, "reset LOAD");
        expect_reg(A_COUNT,  32'd0, "reset COUNT");
        expect_reg(A_STATUS, 32'd0, "reset STATUS");
        expect_irq(1'b0, "reset irq");

        // B: register widths; all wdata and load bits toggle
        write(A_LOAD, 32'hFFFF_FFFF);
        expect_reg(A_LOAD, 32'h0000_FFFF, "LOAD keeps W bits");
        expect_reg(A_CTRL, 32'd0, "CTRL untouched");
        write(A_CTRL, 32'hFFFF_FFF8);
        expect_reg(A_CTRL, 32'd0, "CTRL ignores upper bits");
        expect_reg(A_COUNT, 32'd0, "COUNT idle");

        // C: start reloads the count; stop holds it
        write(A_CTRL, 32'h1);
        expect_reg(A_CTRL, 32'h1, "CTRL EN");
        expect_reg(A_COUNT, 32'h0000_FFFF, "start reloads 0xFFFF");
        tick(1);
        expect_reg(A_COUNT, 32'h0000_FFFE, "decrement");
        write(A_CTRL, 32'h0);
        expect_reg(A_COUNT, 32'h0000_FFFE, "CTRL write replaces decrement");
        expect_reg(A_CTRL, 32'h0, "stopped");
        tick(2);
        expect_reg(A_COUNT, 32'h0000_FFFE, "stopped count holds");
        expect_reg(A_STATUS, 32'h0, "no expiry while stopped");

        // D: zero load, one-shot expiry, IE gating, W1C clear
        write(A_LOAD, 32'h0);
        expect_reg(A_LOAD, 32'h0, "LOAD 0");
        write(A_CTRL, 32'h1);
        expect_reg(A_COUNT, 32'h0, "start reloads 0");
        expect_reg(A_STATUS, 32'h0, "not yet expired");
        expect_reg(A_CTRL, 32'h1, "running");
        tick(1);
        expect_reg(A_STATUS, 32'h1, "zero-load expiry");
        expect_reg(A_CTRL, 32'h0, "one-shot stops");
        expect_reg(A_COUNT, 32'h0, "count stays 0");
        expect_irq(1'b0, "irq masked by IE=0");
        write(A_CTRL, 32'h4);
        expect_reg(A_CTRL, 32'h4, "IE set");
        expect_irq(1'b1, "irq with IE=1");
        write(A_STATUS, 32'hFFFF_FFFE);
        expect_reg(A_STATUS, 32'h1, "write 0 to bit 0 keeps EXPIRED");
        expect_irq(1'b1, "irq held");
        write(A_STATUS, 32'h1);
        expect_reg(A_STATUS, 32'h0, "W1C clears EXPIRED");
        expect_irq(1'b0, "irq cleared");

        // E: one-shot, load 3, exact expiry timing
        write(A_LOAD, 32'h3);
        write(A_CTRL, 32'h5);
        expect_reg(A_COUNT, 32'h3, "one-shot start 3");
        expect_reg(A_STATUS, 32'h0, "E status 0");
        tick(1);
        expect_reg(A_COUNT, 32'h2, "count 2");
        tick(1);
        expect_reg(A_COUNT, 32'h1, "count 1");
        tick(1);
        expect_reg(A_COUNT, 32'h0, "count 0");
        expect_reg(A_STATUS, 32'h0, "not expired at zero");
        expect_irq(1'b0, "no irq at zero");
        tick(1);
        expect_reg(A_STATUS, 32'h1, "one-shot expiry");
        expect_reg(A_CTRL, 32'h4, "one-shot cleared EN");
        expect_reg(A_COUNT, 32'h0, "one-shot count 0");
        expect_irq(1'b1, "one-shot irq");
        tick(1);
        expect_reg(A_COUNT, 32'h0, "stays 0 after stop");
        expect_reg(A_CTRL, 32'h4, "stays stopped");
        write(A_STATUS, 32'h1);
        expect_reg(A_STATUS, 32'h0, "E clear");
        expect_irq(1'b0, "E irq cleared");

        // F: periodic, load 2
        write(A_LOAD, 32'h2);
        write(A_CTRL, 32'h7);
        expect_reg(A_COUNT, 32'h2, "periodic start 2");
        expect_reg(A_CTRL, 32'h7, "periodic CTRL");
        tick(1);
        expect_reg(A_COUNT, 32'h1, "periodic 1");
        tick(1);
        expect_reg(A_COUNT, 32'h0, "periodic 0");
        expect_reg(A_STATUS, 32'h0, "periodic not yet");
        tick(1);
        expect_reg(A_COUNT, 32'h2, "periodic reload");
        expect_reg(A_STATUS, 32'h1, "periodic expiry");
        expect_reg(A_CTRL, 32'h7, "periodic keeps EN");
        expect_irq(1'b1, "periodic irq");
        write(A_STATUS, 32'h1);
        expect_reg(A_STATUS, 32'h0, "periodic clear");
        expect_reg(A_COUNT, 32'h1, "periodic 1 again");
        expect_irq(1'b0, "periodic irq cleared");
        tick(1);
        expect_reg(A_COUNT, 32'h0, "periodic 0 again");
        write(A_STATUS, 32'h1);
        expect_reg(A_STATUS, 32'h1, "expiry wins over same-edge clear");
        expect_reg(A_COUNT, 32'h2, "reload at contested edge");
        write(A_STATUS, 32'h1);
        expect_reg(A_STATUS, 32'h0, "clear after contest");
        expect_reg(A_COUNT, 32'h1, "count 1 after contest");
        tick(1);
        expect_reg(A_COUNT, 32'h0, "count 0 before CTRL write");
        write(A_CTRL, 32'h7);
        expect_reg(A_STATUS, 32'h0, "CTRL write suppresses expiry");
        expect_reg(A_COUNT, 32'h0, "no reload when already running");
        expect_reg(A_CTRL, 32'h7, "still periodic");
        tick(1);
        expect_reg(A_STATUS, 32'h1, "expiry one edge later");
        expect_reg(A_COUNT, 32'h2, "reload one edge later");
        write(A_CTRL, 32'h5);
        expect_reg(A_COUNT, 32'h2, "mode switch holds count");
        expect_reg(A_CTRL, 32'h5, "now one-shot");
        write(A_STATUS, 32'h1);
        expect_reg(A_STATUS, 32'h0, "clear during one-shot");
        expect_reg(A_COUNT, 32'h1, "one-shot 1");
        tick(1);
        expect_reg(A_COUNT, 32'h0, "one-shot 0");
        expect_reg(A_STATUS, 32'h0, "one-shot not yet");
        tick(1);
        expect_reg(A_STATUS, 32'h1, "switched one-shot expiry");
        expect_reg(A_CTRL, 32'h4, "switched one-shot stops");
        expect_reg(A_COUNT, 32'h0, "switched one-shot count");
        expect_irq(1'b1, "switched one-shot irq");

        // G: reset asserted mid-run
        write(A_LOAD, 32'h5);
        write(A_CTRL, 32'h7);
        tick(2);
        expect_reg(A_COUNT, 32'h3, "running before reset");
        expect_reg(A_STATUS, 32'h1, "expired before reset");
        expect_irq(1'b1, "irq before reset");
        rst_n = 1'b0;
        tick(1);
        rst_n = 1'b1;
        expect_reg(A_CTRL,   32'd0, "mid-run reset CTRL");
        expect_reg(A_LOAD,   32'd0, "mid-run reset LOAD");
        expect_reg(A_COUNT,  32'd0, "mid-run reset COUNT");
        expect_reg(A_STATUS, 32'd0, "mid-run reset STATUS");
        expect_irq(1'b0, "mid-run reset irq");
        tick(2);
        expect_reg(A_COUNT, 32'd0, "idle after reset");
        expect_reg(A_STATUS, 32'd0, "no expiry after reset");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
